import{_ as l,o as t,c as a,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Orchestrator Meeting 2022-10-18","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2022-10-18","date":"2022-10-18T00:00:00.000Z","updated":"2022-10-19T00:00:00.000Z","tags":["Ceph基准测试","存储后端比较","CBT工具","Ceph性能","后端兼容性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-10-18.md","filePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-10-18.md","lastUpdated":1780459816000}'),i={name:"posts/2022/Ceph_Orchestrator_Meeting_2022-10-18.md"};function o(s,e,n,h,p,u){return t(),a("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph基准测试与不同存储后端的比较" tabindex="-1">会议主题：Ceph基准测试与不同存储后端的比较 <a class="header-anchor" href="#会议主题-ceph基准测试与不同存储后端的比较" aria-label="Permalink to &quot;会议主题：Ceph基准测试与不同存储后端的比较&quot;">​</a></h4><h4 id="主要讨论内容" tabindex="-1">主要讨论内容： <a class="header-anchor" href="#主要讨论内容" aria-label="Permalink to &quot;主要讨论内容：&quot;">​</a></h4><ol><li><p><strong>CBT工具的使用</strong>：</p><ul><li>讨论了使用Ceph Benchmarking Tools (CBT)来比较不同的存储后端，特别是针对不同的zipper后端。</li><li>提到了DB store可能是一个可以运行的后端，但对于其他后端的状态不确定是否能够通过这些工作负载。</li></ul></li><li><p><strong>后端状态与兼容性</strong>：</p><ul><li>讨论了Motor和Deos后端的状态，特别是它们是否已经合并到上游以及是否需要特殊硬件。</li><li>确认Motor是开源的，但不确定是否需要Seagate硬件。Deos是Intel的产品。</li></ul></li><li><p><strong>CBT集群抽象</strong>：</p><ul><li>讨论了改进CBT集群抽象的必要性，使其不仅仅支持Ceph。</li><li>提到了可能首先支持Deos，然后扩展CBT的客户端端点以支持不同的操作。</li></ul></li><li><p><strong>功能实现与性能</strong>：</p><ul><li>讨论了Deos的一些基本功能如put、delete、bucket listing已经实现，但multipart upload等功能尚未实现。</li><li>提到了Deos在Lenovo的IO-500测试中表现出色，尤其是在未启用复制模式时。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>Mark计划首先尝试安装和运行Deos，并记录部署过程，以便后续自动化。</li><li>计划与Seagate合作，特别是与Gregory Tarletsky联系，以获取更多技术支持和合作。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>确定使用CBT工具进行不同后端的基准测试。</li><li>确认与Seagate的合作，特别是关于Motor和Deos后端的测试和集成。</li></ul><h4 id="后续行动" tabindex="-1">后续行动： <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动：&quot;">​</a></h4><ul><li>Mark将尝试安装和运行Deos，并记录部署过程。</li><li>将与Seagate的Gregory Tarletsky联系，以获取更多技术支持和合作。</li><li>继续改进CBT集群抽象，使其支持更多类型的存储后端。</li></ul><h4 id="其他讨论点" tabindex="-1">其他讨论点： <a class="header-anchor" href="#其他讨论点" aria-label="Permalink to &quot;其他讨论点：&quot;">​</a></h4><ul><li>讨论了RBD和RGW的性能改进，特别是与SEO的集成可能带来的性能提升。</li><li>提到了多站点重启问题的复杂性，以及客户端性能优化的潜力。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在讨论了所有议程后结束，感谢所有参与者的贡献和讨论。</li></ul><p>在原始字幕中，有几点信息未被完整总结：</p><ol><li><strong>Deos的性能测试</strong>：字幕中提到了Deos在IO-500测试中的出色表现，但总结中未提及。</li><li><strong>其他存储后端</strong>：字幕中提到了Motor和Deos之外的其他后端，如DB store，但总结中未提及。</li><li><strong>性能优化</strong>：字幕中讨论了性能优化的潜在点，如多站点重启问题和客户端性能。</li></ol><p>改进后的总结已包含以上信息，并保留了所有相关的Ceph和计算机科学领域的英文关键词。</p>',15)])])}const g=l(i,[["render",o]]);export{c as __pageData,g as default};
